import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.BrrkjrmM.js";const u=JSON.parse('{"title":"API Service 概述","description":"","frontmatter":{},"headers":[],"relativePath":"api-service/index.md","filePath":"api-service/index.md","lastUpdated":1780565711000}'),r={name:"api-service/index.md"};function d(o,e,i,p,l,c){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="api-service-概述" tabindex="-1">API Service 概述 <a class="header-anchor" href="#api-service-概述" aria-label="Permalink to &quot;API Service 概述&quot;">​</a></h1><p><code>@nimble-api/api-service</code> 是一个功能完备的 TypeScript API 客户端框架，构建于 <code>@nimble-api/eventhub</code> 之上，提供缓存、重试、钩子、适配器等企业级特性。</p><h2 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to &quot;设计理念&quot;">​</a></h2><ul><li><strong>可插拔适配器</strong> — 实现 <code>RequestAdapter</code> 接口即可接入任意 HTTP 层</li><li><strong>钩子管线</strong> — 覆盖请求生命周期的 4 个节点，支持状态修改和中止</li><li><strong>智能缓存</strong> — LRU + TTL + SWR 三模式，支持标签批量失效</li><li><strong>类型优先</strong> — 请求/响应/选项全链路类型安全</li></ul><h2 id="架构概览" tabindex="-1">架构概览 <a class="header-anchor" href="#架构概览" aria-label="Permalink to &quot;架构概览&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌──────────────────────────┐</span></span>
<span class="line"><span>                    │       ApiClient           │</span></span>
<span class="line"><span>                    │                           │</span></span>
<span class="line"><span>  get/post/    ──►  │  #request()              │</span></span>
<span class="line"><span>  put/patch/        │    ├─ beforeRequest hooks │</span></span>
<span class="line"><span>  delete            │    ├─ cache check         │</span></span>
<span class="line"><span>                    │    ├─ adapter.request()   │</span></span>
<span class="line"><span>                    │    ├─ schema validate     │</span></span>
<span class="line"><span>                    │    ├─ afterResponse hooks │</span></span>
<span class="line"><span>                    │    ├─ cache store         │</span></span>
<span class="line"><span>                    │    └─ event dispatch      │</span></span>
<span class="line"><span>                    │                           │</span></span>
<span class="line"><span>                    │  依赖:                    │</span></span>
<span class="line"><span>                    │   ├─ MemoryCache          │</span></span>
<span class="line"><span>                    │   ├─ RequestAdapter       │</span></span>
<span class="line"><span>                    │   ├─ EventHub             │</span></span>
<span class="line"><span>                    │   └─ Hooks pipeline       │</span></span>
<span class="line"><span>                    └──────────────────────────┘</span></span></code></pre></div><h2 id="请求生命周期" tabindex="-1">请求生命周期 <a class="header-anchor" href="#请求生命周期" aria-label="Permalink to &quot;请求生命周期&quot;">​</a></h2><p>一次完整的请求经过以下阶段：</p><ol><li><strong>beforeRequest 钩子</strong> — 修改请求配置（URL、headers、body）</li><li><strong>请求去重检查</strong> — 相同请求并发只发一次</li><li><strong>缓存检查</strong> — TTL 命中直接返回 / SWR 命中返回旧值后台刷新</li><li><strong>适配器请求</strong> — 实际 HTTP 调用</li><li><strong>Schema 校验</strong> — <code>parse()</code> 或 <code>safeParse()</code> 验证响应</li><li><strong>状态码检查</strong> — 非 2xx 抛出 <code>ApiError</code></li><li><strong>afterResponse 钩子</strong> — 后置处理（逆序执行）</li><li><strong>缓存存储</strong> — 写入缓存 + 提取实体标签</li><li><strong>事件派发</strong> — 通过 EventHub 发射 onSuccess/onError 事件</li><li><strong>重试（失败时）</strong> — beforeRetry → backoff → 重新发起</li></ol><h2 id="核心类" tabindex="-1">核心类 <a class="header-anchor" href="#核心类" aria-label="Permalink to &quot;核心类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类/函数</th><th>说明</th></tr></thead><tbody><tr><td><code>ApiClient</code></td><td>HTTP 客户端主类</td></tr><tr><td><code>createApiClient()</code></td><td>工厂函数</td></tr><tr><td><code>MemoryCache</code></td><td>LRU 内存缓存（可独立使用）</td></tr><tr><td><code>ApiError</code></td><td>结构化请求错误</td></tr></tbody></table><h2 id="核心工具函数" tabindex="-1">核心工具函数 <a class="header-anchor" href="#核心工具函数" aria-label="Permalink to &quot;核心工具函数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>calcBackoff()</code></td><td>计算重试延迟</td></tr><tr><td><code>shouldRetry()</code></td><td>判断是否应重试</td></tr><tr><td><code>runBeforeRequest()</code></td><td>运行 beforeRequest 钩子链</td></tr><tr><td><code>runAfterResponse()</code></td><td>运行 afterResponse 钩子链</td></tr><tr><td><code>runBeforeRetry()</code></td><td>运行 beforeRetry 钩子链</td></tr><tr><td><code>runBeforeError()</code></td><td>运行 beforeError 钩子链</td></tr><tr><td><code>createFetchAdapter()</code></td><td>创建 fetch 适配器</td></tr><tr><td><code>createUniAppAdapter()</code></td><td>创建 uni-app 适配器</td></tr><tr><td><code>createTypedApi()</code></td><td>创建类型安全的端点包装器</td></tr></tbody></table>`,13)])])}const b=t(r,[["render",d]]);export{u as __pageData,b as default};
